// === DAILY REPORT AGGREGATOR ===
const items = $input.all();
const now = new Date();
const oneDayAgo = new Date(now.getTime() - 24 * 60 * 60 * 1000);

// Filter last 24 hours alerts
const recentAlerts = items.filter(item => {
  const ts = new Date(item.json.Timestamp);
  return ts >= oneDayAgo;
});

const totalAlerts = recentAlerts.length;

if (totalAlerts === 0) {
  return [{
    json: {
      period: `${oneDayAgo.toISOString().slice(0,10)} → ${now.toISOString().slice(0,10)}`,
      total_alerts: 0,
      avg_confidence: 'N/A',
      most_critical_node: 'None',
      autonomous_actions: 0,
      human_reviews: 0,
      escalated: 0,
      network_health: '100%',
      severity_breakdown: 'No alerts',
      has_data: false
    }
  }];
}

const confidences = recentAlerts
  .map(a => parseFloat(a.json.Confidence))
  .filter(c => !isNaN(c));
const avgConfidence = confidences.length > 0
  ? (confidences.reduce((a, b) => a + b, 0) / confidences.length).toFixed(2)
  : 'N/A';

const severityCounts = {};
recentAlerts.forEach(a => {
  const sev = a.json.Severity || 'UNKNOWN';
  severityCounts[sev] = (severityCounts[sev] || 0) + 1;
});

const nodeCounts = {};
recentAlerts.forEach(a => {
  const node = a.json.Node || 'Unknown';
  nodeCounts[node] = (nodeCounts[node] || 0) + 1;
});
const mostCriticalNode = Object.entries(nodeCounts)
  .sort((a, b) => b[1] - a[1])[0];

const autonomousCount = recentAlerts.filter(a => a.json.Escalation === 'AUTONOMOUS').length;
const humanReviewCount = recentAlerts.filter(a => a.json.Escalation === 'HUMAN_REVIEW').length;
const escalatedCount = recentAlerts.filter(a => a.json.Escalation === 'ESCALATED').length;

const criticalCount = (severityCounts['CRITICAL'] || 0);
const highCount = (severityCounts['HIGH'] || 0);
const healthScore = Math.max(0, 100 - (criticalCount * 20) - (highCount * 10));

return [{
  json: {
    period: `${oneDayAgo.toISOString().slice(0,10)} → ${now.toISOString().slice(0,10)}`,
    total_alerts: totalAlerts,
    avg_confidence: avgConfidence,
    most_critical_node: mostCriticalNode ? `${mostCriticalNode[0]} (${mostCriticalNode[1]} alerts)` : 'None',
    autonomous_actions: autonomousCount,
    human_reviews: humanReviewCount,
    escalated: escalatedCount,
    network_health: `${healthScore}%`,
    severity_breakdown: Object.entries(severityCounts).map(([k,v]) => `${k}: ${v}`).join(', '),
    has_data: true
  }
}];

